void mainImage( out vec4 O, vec2 u )
{
    vec2 R = iResolution.xy,
         U = 2.*( 2.*u - R ) / R.y, 
         A;
    float s =  .1*iTime;
    O *= 0.;

    H(U);                                         // distortion
    A = abs(U);
    if ( max(A.x,A.y) > 1.5 ) return;             // out of cube

    for( int z;                                   // fractal loop
         z++ < int(log(R.y)/1.1)-1; 
         U = 3.*fract(U+.5)- 1.5                  // recursion
       ) {
     // s = -s;
        H(U);                                     // distortion
        if ( round(U) == U-U ) return;            // black square       
    }
    O++;                                          // paint white
}
